<?php
require __DIR__ . '/../lib/bootstrap.php';$user=auth_user();if($_SERVER['REQUEST_METHOD']!=='POST')fail('Method not allowed',405);$d=input();$action=(string)($d['action']??'start');if($action==='start'){$recipient=(int)($d['recipient_id']??0);$type=(string)($d['type']??'audio');if(!in_array($type,['audio','video'],true)||$recipient<1)fail('Invalid call');$session=random_token(24);$st=db()->prepare('INSERT INTO calls(caller_id,recipient_id,type,status,session_token_hash,created_at,expires_at) VALUES(?,?,?,"ringing",SHA2(?,256),UTC_TIMESTAMP(),UTC_TIMESTAMP()+INTERVAL 2 MINUTE)');$st->execute([$user['id'],$recipient,$type,$session]);out(['call_id'=>(int)db()->lastInsertId(),'signaling_token'=>$session,'status'=>'ringing'],201);}if(in_array($action,['accept','decline','end'],true)){$id=(int)($d['call_id']??0);$status=$action==='accept'?'accepted':($action==='decline'?'declined':'ended');$st=db()->prepare('UPDATE calls SET status=?,updated_at=UTC_TIMESTAMP() WHERE id=? AND (caller_id=? OR recipient_id=?)');$st->execute([$status,$id,$user['id'],$user['id']]);out(['status'=>$status]);}fail('Invalid action');
